  const first=files.find(f=>f[0]==='xl/worksheets/sheet1.xml');first[1]=first[1].replace('<c r="A1" t="inlineStr"><is><t>Product Name</t></is></c>','<c t="s" r="A1"><v>0</v></c>').replace('<c r="B2" t="inlineStr"><is><t>Cotton</t></is></c>','<c t="str" r="B2"><f>"Cotton"</f><v>Cotton</v></c>');
  let offset=0;const data=[],directory=[];for(const [name,text]of files){const filename=Buffer.from(name),raw=Buffer.from(text),packed=deflateRawSync(raw),check=crc(raw),local=Buffer.alloc(30),central=Buffer.alloc(46);local.writeUInt32LE(0x04034b50,0);local.writeUInt16LE(20,4);local.writeUInt16LE(8,8);local.writeUInt32LE(check,14);local.writeUInt32LE(packed.length,18);local.writeUInt32LE(raw.length,22);local.writeUInt16LE(filename.length,26);central.writeUInt32LE(0x02014b50,0);central.writeUInt16LE(20,4);central.writeUInt16LE(20,6);central.writeUInt16LE(8,10);central.writeUInt32LE(check,16);central.writeUInt32LE(packed.length,20);central.writeUInt32LE(raw.length,24);central.writeUInt16LE(filename.length,28);central.writeUInt32LE(offset,42);data.push(local,filename,packed);directory.push(central,filename);offset+=local.length+filename.length+packed.length;}
